import{_ as i,o as l,c as t,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"Ceph for Big Science - Dan van der Ster","description":"","frontmatter":{"title":"Ceph for Big Science - Dan van der Ster","date":"2018-04-23T00:00:00.000Z","updated":"2018-04-23T00:00:00.000Z","tags":["Ceph","分布式存储","科学计算","高性能计算","CERN"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_for_Big_Science_-_Dan_van_der_Ster.md","filePath":"posts/2018/Ceph_for_Big_Science_-_Dan_van_der_Ster.md","lastUpdated":1780459816000}'),r={name:"posts/2018/Ceph_for_Big_Science_-_Dan_van_der_Ster.md"};function _(p,e,a,C,o,s){return l(),t("div",null,[...e[0]||(e[0]=[n("<p>CERN使用Ceph进行大规模科学存储的会议中，Dan van der Ster分享了CERN在Ceph方面的应用经验和改进建议。</p><p><strong>会议要点</strong>：</p><ul><li><strong>CERN背景介绍</strong>：CERN是世界上最大的粒子加速器，拥有庞大的存储和计算资源，是全球LHC计算网格的一部分。</li><li><strong>Ceph在CERN的应用</strong>： <ul><li>CERN使用Ceph存储大量科学数据，包括实验数据、虚拟文件系统等。</li><li>CERN的存储集群已扩展至8个生产集群，存储量接近6PB。</li><li>Ceph用于OpenStack Cinder、Glance、CFS、物理数据存储和S3对象存储。</li><li>Ceph文件系统（SFS）用于替代虚拟NFS文件系统，提供高可用性和可扩展性。</li><li>Ceph块设备（RBD）用于存储Glance镜像和Cinder卷。</li></ul></li><li><strong>Ceph改进建议</strong>： <ul><li>开发RBD性能监控工具，提高性能和可靠性。</li><li>改善SEF文件系统的并行I/O性能，提高HPC存储性能。</li><li>支持池级别对象备份，例如从副本复制到快照。</li><li>解决大型集群的配置和升级问题。</li></ul></li><li><strong>未来展望</strong>： <ul><li>CERN预计在2020年代将产生数百PB的数据，需要更强大的存储系统。</li><li>CERN正在与Ceph社区合作，进行大规模测试，验证Ceph的扩展性。</li><li>CERN希望将Ceph用于更多存储场景，包括全球数据湖。</li></ul></li></ul><p><strong>行动计划</strong>：</p><ul><li>CERN将继续与Ceph社区合作，推动Ceph的改进。</li><li>CERN将进行更多测试，验证Ceph在大型集群中的性能和可靠性。</li><li>CERN将探索将Ceph用于更多存储场景的可能性。</li></ul><p><strong>关键词</strong>： CERN、Ceph、OpenStack、Cinder、Glance、S3、RBD、SFS、HPC、数据湖</p>",6)])])}const d=i(r,[["render",_]]);export{S as __pageData,d as default};
